package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/internal/coreapi"
)

// mirrorColumns is the human table/field view of a mirror: the scannable
// owner/repo name, the clone URL you'd copy, and whether the upstream is
// private. Owner, provider, and cluster aren't columns of their own — they're
// inferable from the owner/repo pair and the clone URL
// (entire://<cluster>/gh/<owner>/<repo>), where `--repo` and a bare cluster/
// provider substring still match — and the wire model's internal ids are
// dropped. The clone URL is synthesised from the mirror's coords (the form
// `git clone` accepts), since the list API doesn't return it.
var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}

func mirrorRow(m coreapi.Mirror) []string {
	repo := m.Owner + "/" + m.Repo
	cloneURL := mirrorCloneURL(m.ClusterHost, m.Owner, m.Repo)
	private := "no"
	if m.IsPrivate.Or(false) {
		private = "yes"
	}
	return []string{repo, cloneURL, private}
}

// sortMirrorsDefault orders mirrors by the owner/repo name ascending (matching
// the REPO column and an explicit `--sort repo`), breaking ties by cluster host
// ascending. It's the default (no --sort) ordering: a repo mirrored on several
// clusters would otherwise sit in arbitrary server order. Case-insensitive,
// matching sortRows.
func sortMirrorsDefault(mirrors []coreapi.Mirror) {
	sort.SliceStable(mirrors, func(i, j int) bool {
		ri := strings.ToLower(mirrors[i].Owner + "/" + mirrors[i].Repo)
		rj := strings.ToLower(mirrors[j].Owner + "/" + mirrors[j].Repo)
		if ri != rj {
			return ri < rj
		}
		return strings.ToLower(mirrors[i].ClusterHost) < strings.ToLower(mirrors[j].ClusterHost)
	})
}

// sortRows orders items in place by one column's rendered value, ascending
// case-insensitive string order. spec is a header name; a leading '-' sorts
// descending. An empty spec sorts by the first column. An unknown column name
// is an error naming the valid columns. Stable, so rows equal on the sort
// column keep their input order. row must return one cell per header, which the
// mirror/available row funcs do.
func sortRows[T any](items []T, headers []string, row func(T) []string, spec string) error {
	desc := strings.HasPrefix(spec, "-")
	name := strings.ToLower(strings.TrimSpace(strings.TrimPrefix(spec, "-")))
	idx := 0
	if name != "" {
		idx = -1
		for i, h := range headers {
			if strings.EqualFold(h, name) {
				idx = i
				break
			}
		}
		if idx < 0 {
			return fmt.Errorf("unknown sort column %q; valid columns: %s", name, strings.ToLower(strings.Join(headers, ", ")))
		}
	}
	sort.SliceStable(items, func(a, b int) bool {
		ka, kb := strings.ToLower(row(items[a])[idx]), strings.ToLower(row(items[b])[idx])
		if desc {
			return ka > kb
		}
		return ka < kb
	})
	return nil
}

// filterByRepo keeps items whose repo name contains substr (case-insensitive).
// The control plane already filters by owner/provider/cluster server-side but
// not by repo name, so `repo mirror list --repo` narrows that last dimension
// client-side. repoOf extracts the repo field from each item (mirrors and
// available mirrors both carry one). An empty substr returns items unchanged.
func filterByRepo[T any](items []T, repoOf func(T) string, substr string) []T {
	substr = strings.TrimSpace(substr)
	if substr == "" {
		if items == nil {
			return []T{}
		}
		return items
	}
	substr = strings.ToLower(substr)
	out := make([]T, 0, len(items))
	for _, it := range items {
		if strings.Contains(strings.ToLower(repoOf(it)), substr) {
			out = append(out, it)
		}
	}
	return out
}

// availableMirrorColumns is the view of a repo you *could* mirror: the
// scannable repo name, your effective GitHub access, and whether it's
// onboardable. STATUS is "available" (run `entire repo mirror create` to
// onboard), "mirrored" (already done — `entire repo mirror list` shows the
// clone URL), or "owner-only" (a personal repo of another user; only its
// owner may mirror it). No clone URL column: an un-onboarded repo doesn't
// have one yet.
var availableMirrorColumns = []string{"REPO", "ACCESS", "STATUS"}

func availableMirrorRow(m coreapi.AvailableMirror) []string {
	return []string{m.Owner + "/" + m.Repo, string(m.Access), string(m.Status)}
}

// defaultClusterHost is the cluster the positional-arg mirror commands target
// when the caller omits the <cluster-host> argument. The no-arg create wizard
// and the interactive one-shot `create <github-url>` instead enumerate real
// clusters from the catalog (GET /api/v1/clusters, see availableRegions and
// resolveOneShotClusterHost in repo_mirror_create_wizard.go); this stays as
// the fixed fallback for non-interactive invocations, so scripts keep a
// stable, offline-resolvable default.

