21	// mirrorColumns is the human table/field view of a mirror: the scannable
22	// owner/repo name, the clone URL you'd copy, and whether the upstream is
23	// private. Owner, provider, and cluster aren't columns of their own — they're
24	// inferable from the owner/repo pair and the clone URL
25	// (entire://<cluster>/gh/<owner>/<repo>). `--repo` filters on the repo name
26	// only; owner/provider/cluster stay server-side filters, and the wire model's
27	// internal ids are dropped. The clone URL is synthesised from the mirror's
28	// coords (the form `git clone` accepts), since the list API doesn't return it.
29	var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}
30	
31	// mirrorPrivate renders the PRIVATE column ("yes"/"no"), shared by the table
32	// row and the --sort private key so both agree on the cell value.
33	func mirrorPrivate(m coreapi.Mirror) string {
34		if m.IsPrivate.Or(false) {
35			return "yes"
36		}
37		return "no"
38	}
39	
40	func mirrorRow(m coreapi.Mirror) []string {
41		repo := m.Owner + "/" + m.Repo
42		cloneURL := mirrorCloneURL(m.ClusterHost, m.Owner, m.Repo)
43		return []string{repo, cloneURL, mirrorPrivate(m)}
44	}
