46	// parseSortColumn resolves a --sort spec to a lowercased column name and
47	// direction against columns. It trims first, then reads the '-' prefix, so
48	// leading/trailing whitespace is handled identically on every path (the
49	// direction and the column name never disagree). An empty spec selects the
50	// first column. An unknown name errors naming the valid columns.
51	func parseSortColumn(spec string, columns []string) (col string, desc bool, err error) {
52		spec = strings.TrimSpace(spec)
53		desc = strings.HasPrefix(spec, "-")
54		name := strings.ToLower(strings.TrimSpace(strings.TrimPrefix(spec, "-")))
55		if name == "" {
56			return strings.ToLower(columns[0]), desc, nil
57		}
58		for _, h := range columns {
59			if strings.EqualFold(h, name) {
60				return name, desc, nil
61			}
62		}
63		return "", false, fmt.Errorf("unknown sort column %q; valid columns: %s", name, strings.ToLower(strings.Join(columns, ", ")))
64	}
65	
66	// sortMirrors orders mirrors in place by the --sort spec: by the named column's
67	// value ascending (case-insensitive), always breaking ties by owner/repo then
68	// cluster host so a repo mirrored across clusters (or rows equal on any other
69	// column) has a stable, deterministic order rather than arbitrary server order.
70	// A '-' prefix reverses the whole ordering. `repo`/default sorts by the
71	// tiebreak alone.
72	func sortMirrors(mirrors []coreapi.Mirror, spec string) error {
73		col, desc, err := parseSortColumn(spec, mirrorColumns)
74		if err != nil {
75			return err
76		}
77		key := func(m coreapi.Mirror) string {
78			switch col {
79			case "clone url":
80				return strings.ToLower(mirrorCloneURL(m.ClusterHost, m.Owner, m.Repo))
81			case "private":
82				return mirrorPrivate(m)
83			default: // repo -> tiebreak alone
84				return ""
85			}
86		}
87		slices.SortStableFunc(mirrors, func(a, b coreapi.Mirror) int {
88			c := cmp.Compare(key(a), key(b))
89			if c == 0 {
90				c = cmp.Compare(strings.ToLower(a.Owner+"/"+a.Repo), strings.ToLower(b.Owner+"/"+b.Repo))
91			}
92			if c == 0 {
93				c = cmp.Compare(strings.ToLower(a.ClusterHost), strings.ToLower(b.ClusterHost))
94			}
95			if desc {
96				return -c
97			}
98			return c
99		})
100		return nil
101	}
102	
103	// sortAvailable orders available mirrors in place by the --sort spec, matching
104	// sortMirrors: by the named column ascending (case-insensitive) with an
105	// owner/repo tiebreak for a deterministic order on equal keys. AvailableMirror
106	// has no cluster host (the onboardable set is cluster-agnostic), so owner/repo
107	// is the only secondary key. A '-' prefix reverses the whole ordering.
108	func sortAvailable(avail []coreapi.AvailableMirror, spec string) error {
109		col, desc, err := parseSortColumn(spec, availableMirrorColumns)
110		if err != nil {
111			return err
112		}
113		key := func(m coreapi.AvailableMirror) string {
114			switch col {
115			case "access":
116				return strings.ToLower(string(m.Access))
117			case "status":
118				return strings.ToLower(string(m.Status))
119			default: // repo -> tiebreak alone
120				return ""
121			}
122		}
123		slices.SortStableFunc(avail, func(a, b coreapi.AvailableMirror) int {
124			c := cmp.Compare(key(a), key(b))
125			if c == 0 {
126				c = cmp.Compare(strings.ToLower(a.Owner+"/"+a.Repo), strings.ToLower(b.Owner+"/"+b.Repo))
127			}
128			if desc {
129				return -c
130			}
131			return c
132		})
133		return nil
134	}
135	
136	// filterByRepo keeps items whose repo name contains substr (case-insensitive).
137	// The control plane already filters by owner/provider/cluster server-side but
138	// not by repo name, so `repo mirror list --repo` narrows that last dimension
139	// client-side. repoOf extracts the repo field from each item (mirrors and
140	// available mirrors both carry one). An empty substr returns items unchanged.
141	func filterByRepo[T any](items []T, repoOf func(T) string, substr string) []T {
142		substr = strings.TrimSpace(substr)
143		if substr == "" {
144			return items
145		}
146		substr = strings.ToLower(substr)
147		out := make([]T, 0, len(items))
148		for _, it := range items {
149			if strings.Contains(strings.ToLower(repoOf(it)), substr) {
150				out = append(out, it)
151			}
152		}
153		return out
154	}
155	
156	// availableMirrorColumns is the view of a repo you *could* mirror: the
157	// scannable repo name, your effective GitHub access, and whether it's
158	// onboardable. STATUS is "available" (run `entire repo mirror create` to
159	// onboard), "mirrored" (already done — `entire repo mirror list` shows the
160	// clone URL), or "owner-only" (a personal repo of another user; only its
161	// owner may mirror it). No clone URL column: an un-onboarded repo doesn't
162	// have one yet.
163	var availableMirrorColumns = []string{"REPO", "ACCESS", "STATUS"}
164	
165	func availableMirrorRow(m coreapi.AvailableMirror) []string {
166		return []string{m.Owner + "/" + m.Repo, string(m.Access), string(m.Status)}
167	}
